5. // Imports
6. //==================================================================================================
7. 
8. use vstd::prelude::*;
9. #[cfg(verus_keep_ghost)]
10. include!("manager.spec.rs");
11. #[cfg(verus_keep_ghost)]
12. include!("manager.proof.rs");
13. 
14. use crate::{
15.     hal::mem::FrameAddress,
16.     mm::phys::{
17.         frame,
18.         kframe::KernelFrame,
19.         upool::{
20.             Upool,
21.             UserFrame,
22.         },
23.     },
24. };
25. use ::alloc::vec::Vec;
26. use ::arch::mem;
27. use ::core::{
28.     hint::unlikely,
29.     mem::MaybeUninit,
30.     sync::atomic::{
31.         AtomicBool,
32.         Ordering,
33.     },
34. };
35. use ::sys::error::{
36.     Error,
37.     ErrorCode,
38. };
39. use ::vstd::prelude::*;
40. 
41. //==================================================================================================
42. // Constants
43. //==================================================================================================
44. 
45. // Use relaxed ordering for all atomic operations to mitigate synchronization overhead. It is safe
46. // to use this ordering semantics because Nanvix is a single-core system, and the kernel runs with
47. // interrupts disabled.
48. const ORDER: Ordering = Ordering::Relaxed;
49. 
50. //==================================================================================================
51. // Global Variables
52. //==================================================================================================
53. 
54. /// Physical memory manager storage.
55. static mut PHYS_MEMORY_MANAGER: MaybeUninit<PhysMemoryManager> = MaybeUninit::uninit();
56. 
57. /// Whether the physical memory manager has been initialized.
58. static PHYS_MEMORY_MANAGER_INIT: AtomicBool = AtomicBool::new(false);
59. 
60. //==================================================================================================
61. // Structures
62. //==================================================================================================
63. 
64. ///
65. /// # Description
66. ///
67. /// Physical memory manager.
68. ///
69. pub struct PhysMemoryManager {
70.     upool: Upool,
71. }
72. 
73. //==================================================================================================
74. // Implementations
75. //==================================================================================================
76. 
77. impl PhysMemoryManager {
78.     ///
79.     /// # Description
80.     ///
81.     /// Initializes the physical memory manager singleton.
82.     ///
83.     /// # Parameters
84.     ///
85.     /// - `upool`: User page pool.
86.     ///
87.     /// # Errors
88.     ///
89.     /// Returns `InvalidArgument` if the singleton has already been initialized.
90.     ///
91.     #[verus_verify(external_body)]
92.     pub(super) fn init(upool: Upool) -> Result<(), Error> {
93.         if unlikely(PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
94.             return Err(Error::new(
95.                 ErrorCode::InvalidArgument,
96.                 "physical memory manager already initialized",
97.             ));
98.         }
99. 
100.         // SAFETY: this happens during kernel initialization and no other threads are running.
101.         unsafe { PHYS_MEMORY_MANAGER.write(PhysMemoryManager { upool }) };
102.         PHYS_MEMORY_MANAGER_INIT.store(true, ORDER);
103.         Ok(())
104.     }
105. 
106.     ///
107.     /// # Description
108.     ///
109.     /// Gets a mutable reference to the physical memory manager.
110.     ///
111.     /// # Panics
112.     ///
113.     /// Panics if the physical memory manager is not initialized.
114.     ///
115.     /// # Safety
116.     ///
117.     /// This function is unsafe because it returns a mutable reference to a global variable.
118.     ///
119.     /// The caller must ensure:
120.     ///
121.     /// - No other `&mut PhysMemoryManager` reference obtained from this function is live at the
122.     ///   same time (i.e., `&mut` references must not overlap). In practice this is guaranteed
123.     ///   because the kernel is single-threaded and runs with interrupts disabled, so no
124.     ///   re-entrant or concurrent call can alias the reference.
125.     ///
126.     pub unsafe fn get_mut<'a>() -> &'a mut PhysMemoryManager {
127.         if unlikely(!PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
128.             panic!("physical memory manager is not initialized");
129.         }
130. 
131.         // SAFETY: the physical memory manager has been initialized, so the value is valid.
132.         PHYS_MEMORY_MANAGER.assume_init_mut()
133.     }
134. 
135.     ///
136.     /// # Description
137.     ///
138.     /// Allocates user frames into caller-provided storage.
139.     ///
140.     /// The returned frames are not guaranteed to be physically contiguous.
141.     /// User allocations are gated by the kernel watermark: if fulfilling the request would
142.     /// leave fewer than `KERNEL_WATERMARK` free frames, the allocation is rejected.
143.     ///
144.     /// # Parameters
145.     ///
146.     /// - `count`: Number of frames to allocate.
147.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store those
148.     ///   frames' addresses. It should have sufficient capacity for `count` entries.
149.     ///
150.     /// # Return Values
151.     ///
152.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count` frames. Upon failure, an
153.     /// error is returned and any frames allocated by this call are dropped by truncating `frames`
154.     /// back to empty.
155.     ///
156.     pub fn alloc_many_user_frames(
157.         &mut self,
158.         count: usize,
159.         frames: &mut Vec<UserFrame>,
160.     ) -> Result<(), Error> {
161.         if !frames.is_empty() {
162.             let reason: &str = "frames vector is not empty";
163.             error!("{reason}");
164.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
165.         }
166.         if frames.capacity() < count {
167.             let reason: &str = "frames vector has insufficient capacity";
168.             error!("{reason}");
169.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
170.         }
171. 
172.         // A zero-sized allocation is trivially satisfied.
173.         if count == 0 {
174.             return Ok(());
175.         }
176. 
177.         Self::check_user_watermark(count)?;
178. 
179.         for _ in 0..count {
180.             match self.upool.alloc() {
181.                 Ok(frame) => frames.push(frame),
182.                 Err(error) => {
183.                     frames.clear();
184.                     return Err(error);
185.                 },
186.             }
187.         }
188.         Ok(())
189.     }
190. 
191.     ///
192.     /// # Description
193.     ///
194.     /// Allocates a single user frame, applying the same kernel watermark check as
195.     /// [`Self::alloc_many_user_frames`]. This is the single-frame fast path used on
196.     /// hot paths such as copy-on-write fault resolution, where allocating an
197.     /// intermediate [`Vec`] would be wasteful.
198.     ///
199.     /// # Returns
200.     ///
201.     /// Upon success, a [`UserFrame`] is returned. Upon failure, an error is returned
202.     /// instead.
203.     ///
204.     pub fn alloc_user_frame(&mut self) -> Result<UserFrame, Error> {
205.         Self::check_user_watermark(1)?;
206.         self.upool.alloc()
207.     }
208. 
209.     ///
210.     /// # Description
211.     ///
212.     /// Rejects user allocations of `count` frames that would breach the kernel
213.     /// watermark, i.e. that would drop the number of free frames below
214.     /// [`config::kernel::KERNEL_WATERMARK`].
215.     ///
216.     /// # Parameters
217.     ///
218.     /// - `count`: Number of user frames the caller intends to allocate.
219.     ///
220.     /// # Returns
221.     ///
222.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
223.     ///
224.     fn check_user_watermark(count: usize) -> Result<(), Error> {
225.         let watermark_threshold: usize = config::kernel::KERNEL_WATERMARK
226.             .checked_add(count)
227.             .ok_or_else(|| {
228.                 let reason: &str = "watermark + count overflow";
229.                 error!("{reason}");
230.                 Error::new(ErrorCode::InvalidArgument, reason)
231.             })?;
232.         if frame::free_count() < watermark_threshold {
233.             let reason: &str = "would breach kernel watermark";
234.             error!("{reason}");
235.             return Err(Error::new(ErrorCode::OutOfMemory, reason));
236.         }
237.         Ok(())
238.     }
239. 
240.     ///
241.     /// # Description
242.     ///
243.     /// Allocates a kernel frame.
244.     ///
245.     /// Kernel allocations bypass the watermark — no artificial ceiling.
246.     ///
247.     /// # Return Values
248.     ///
249.     /// Upon success, a kernel frame is returned. Upon failure, an error is returned instead.
250.     ///
251.     pub fn alloc_kernel_frame(&mut self) -> Result<KernelFrame, Error> {
252.         let frame_addr: FrameAddress = frame::alloc()?;
253.         KernelFrame::new(frame_addr).inspect_err(|e| {
254.             warn!("failed to wrap frame after KernelFrame::new failure: {e:?}");
255.             if let Err(free_err) = frame::free(frame_addr) {
256.                 warn!("failed to free frame after KernelFrame::new failure: {free_err:?}");
257.             }
258.         })
259.     }
260. 
261.     ///
262.     /// # Description
263.     ///
264.     /// Allocates a contiguous range of kernel frames into caller-provided storage.
265.     ///
266.     /// Kernel stacks require physically contiguous frames because the kernel uses identity
267.     /// mapping and the hardware stack pointer traverses the region linearly.
268.     /// Kernel allocations bypass the watermark — no artificial ceiling.
269.     ///
270.     /// # Parameters
271.     ///
272.     /// - `count`: Number of frames to allocate.
273.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store
274.     ///   those frames' addresses.
275.     ///
276.     /// # Return Values
277.     ///
278.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count`
279.     /// contiguous entries. Upon failure, an error is returned instead.
280.     ///
281.     pub fn alloc_many_kernel_frames(
282.         &mut self,
283.         count: usize,
284.         frames: &mut Vec<KernelFrame>,
285.     ) -> Result<(), Error> {
286.         // Check if caller-provided vector is not empty.
287.         if !frames.is_empty() {
288.             let reason: &str = "frames vector is not empty";
289.             error!("{reason}");
290.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
291.         }
292.         if frames.capacity() < count {
293.             let reason: &str = "frames vector has insufficient capacity";
294.             error!("{reason}");
295.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
296.         }
297. 
298.         let base_addr: FrameAddress = frame::alloc_contiguous(count)?;
299.         let base_raw: usize = base_addr.into_raw_value();
300.         for i in 0..count {
301.             let raw_addr: usize = base_raw + i * mem::PAGE_SIZE;
302.             match FrameAddress::from_raw_value(raw_addr).and_then(KernelFrame::new) {
303.                 Ok(kf) => frames.push(kf),
304.                 Err(e) => {
305.                     // Drop already-wrapped frames (frees them via KernelFrame::Drop).
306.                     frames.clear();
307.                     // Free remaining un-wrapped frames from the contiguous allocation.
308.                     for j in i..count {
309.                         let leak_raw: usize = base_raw + j * mem::PAGE_SIZE;
310.                         if let Ok(fa) = FrameAddress::from_raw_value(leak_raw) {
311.                             if let Err(e) = frame::free(fa) {
312.                                 warn!("failed to free leaked frame {fa:?}: {e:?}");
313.                             }
314.                         }
315.                     }
316.                     return Err(e);
317.                 },
318.             }
319.         }
320.         Ok(())
321.     }
322. }
